import re
from pathlib import Path

pat = re.compile(r'^(?P<indent>\s+)(?P<name>\w+):\s*(?P<ann>.+?)\s*$')

for path in sorted(Path('cortex_xdr_client').rglob('*.py')):
    text = path.read_text(encoding='utf-8')
    lines = text.splitlines()
    if 'BaseModel' not in text and 'RootModel' not in text:
        continue
    for i, line in enumerate(lines, 1):
        m = pat.match(line)
        if not m:
            continue
        ann = m.group('ann')
        if 'Optional' not in ann and 'None' not in ann:
            continue
        if '=' in ann:
            continue
        print(f'{path}:{i}: {line}')

